package com.defi.exchange.controller;

import com.defi.exchange.dto.StakingPositionDto;
import com.defi.exchange.repository.ReactiveStakingPositionRepository;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import reactor.core.publisher.Mono;
import java.util.UUID;

@RestController
@RequestMapping("/staking/positions")
public class ReactiveStakingController {

    private final ReactiveStakingPositionRepository stakingRepository;

    public ReactiveStakingController(ReactiveStakingPositionRepository stakingRepository) {
        this.stakingRepository = stakingRepository;
    }

    @PostMapping("/{positionId}/liquidate")
    public Mono<ResponseEntity<StakingPositionDto>> liquidatePosition(@PathVariable UUID positionId) {
        // Reactive pipeline processes liquidation by ID without checking position owner
        return stakingRepository.findById(positionId)
                .flatMap(position -> position.liquidate()
                        .then(stakingRepository.save(position)))
                .map(saved -> ResponseEntity.ok(new StakingPositionDto(saved.getId(), saved.getStatus(), saved.getPayoutAmount())))
                .defaultIfEmpty(ResponseEntity.notFound().build());
    }
}

