package com.defi.exchange.controller;

import com.defi.exchange.dto.StakingPositionDto;
import com.defi.exchange.repository.ReactiveStakingPositionRepository;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.web.bind.annotation.*;
import reactor.core.publisher.Mono;
import java.util.UUID;

@RestController
@RequestMapping("/staking/positions")
public class ReactiveStakingController {

    private final ReactiveStakingPositionRepository stakingRepository;

    public ReactiveStakingController(ReactiveStakingPositionRepository stakingRepository) {
        this.stakingRepository = stakingRepository;
    }

    @PostMapping("/{positionId}/liquidate")
    public Mono<ResponseEntity<StakingPositionDto>> liquidatePosition(
            @PathVariable UUID positionId,
            @AuthenticationPrincipal Jwt jwt) {
        String authenticatedWallet = jwt.getClaimAsString("wallet");
        return stakingRepository.findById(positionId)
                .filter(position -> position.getWalletAddress().equalsIgnoreCase(authenticatedWallet))
                .switchIfEmpty(Mono.error(new AccessDeniedException("Caller is not the owner of this staking position")))
                .flatMap(position -> position.liquidate().then(stakingRepository.save(position)))
                .map(saved -> ResponseEntity.ok(new StakingPositionDto(saved.getId(), saved.getStatus(), saved.getPayoutAmount())));
    }
}
